PAGES=[page('084_page_2.jpg',160,[heading('6.4.2 (i) — proof continued'),eq(r'I=x\sqrt{a^2-x^2}+\int\frac{a^2}{\sqrt{a^2-x^2}}\,dx-\int\sqrt{a^2-x^2}\,dx=x\sqrt{a^2-x^2}+a^2\int\frac{dx}{\sqrt{a^2-x^2}}-I'),eq(r'2I=x\sqrt{a^2-x^2}+a^2\sin^{-1}\frac xa+C,\quad\int\frac{dx}{\sqrt{a^2-x^2}}=\sin^{-1}\frac xa'),eq(r'I=\frac{x\sqrt{a^2-x^2}}2+\frac{a^2}2\sin^{-1}\frac xa+\frac C2'),heading('ii. Evaluate ∫√(a²+x²) dx'),heading('Solution'),eq(r'I=\int\sqrt{a^2+x^2}\,dx','i'),paragraph('In this problem, we choose u = √(a²+x²) and dv/dx = 1 to integrate the integrand of (i):'),eq(r'I=x\sqrt{a^2+x^2}-\int\frac{x(x)}{\sqrt{a^2+x^2}}\,dx,\quad\frac{du}{dx}=\frac12(a^2+x^2)^{-1/2}(2x),\quad dv=dx,\quad v=x'),eq(r'=x\sqrt{a^2+x^2}-\int\frac{x^2}{\sqrt{a^2+x^2}}\,dx=x\sqrt{a^2+x^2}-\int\frac{(a^2+x^2)-a^2}{\sqrt{a^2+x^2}}\,dx'),paragraph('add and subtract a²'),eq(r'=x\sqrt{a^2+x^2}+\int\frac{a^2}{\sqrt{a^2+x^2}}\,dx-\int\sqrt{a^2+x^2}\,dx=x\sqrt{a^2+x^2}+a^2\int\frac{dx}{\sqrt{a^2+x^2}}-I'),eq(r'2I=x\sqrt{a^2+x^2}+a^2\ln|x+\sqrt{a^2+x^2}|+C,\quad\int\frac{dx}{\sqrt{a^2+x^2}}=\ln|x+\sqrt{a^2+x^2}|'),eq(r'I=\frac{x\sqrt{a^2+x^2}}2+\frac{a^2}2\ln|x+\sqrt{a^2+x^2}|+\frac C2'),paragraph('Thus,'),eq(r'\int\sqrt{a^2+x^2}\,dx=\frac x2\sqrt{x^2+x^2}+\frac{a^2}2\ln|x+\sqrt{a^2+x^2}|+C'),note('The final source line prints x²+x² in its first radical; the preceding derivation has the correct a²+x². For a > 0 the correct antiderivative is x√(a²+x²)/2 + (a²/2)ln(x+√(a²+x²))+C, valid on ℝ. The inverse-sine formula in (i) also assumes a > 0 and is differentiated on |x| < a.'),heading('iii. Evaluate ∫√(x²−a²) dx'),heading('Solution'),eq(r'I=\int\sqrt{x^2-a^2}\,dx','i'),paragraph('In this problem, we choose u = √(x²−a²) and dv/dx = 1 to integrate the integrand of (i):'),eq(r'I=x\sqrt{x^2-a^2}-\int\frac{x(x)}{\sqrt{x^2-a^2}}\,dx,\quad\frac{du}{dx}=\frac12(x^2-a^2)^{-1/2}2x,\quad dv=dx,\quad v=x'),eq(r'=x\sqrt{x^2-a^2}-\int\frac{x^2}{\sqrt{x^2-a^2}}\,dx=x\sqrt{x^2-a^2}-\int\frac{a^2+(x^2-a^2)}{\sqrt{x^2-a^2}}\,dx'),paragraph('add and subtract a²'),eq(r'=x\sqrt{x^2-a^2}-\int\frac{a^2}{\sqrt{x^2-a^2}}\,dx-\int\sqrt{x^2-a^2}\,dx=x\sqrt{x^2-a^2}-a^2\int\frac{dx}{\sqrt{x^2-a^2}}-I')
]),page('085_page_1.jpg',161,[heading('6.4.2 (iii) — proof continued'),eq(r'I+I=x\sqrt{x^2-a^2}-a^2\ln\left|\frac{\sqrt{x^2-a^2}+x}{|a|}\right|+C'),eq(r'I=\frac{x\sqrt{x^2-a^2}}2-\frac{a^2}2\ln\left|\frac{\sqrt{x^2-a^2}+x}{|a|}\right|+\frac C2'),paragraph('Thus,'),eq(r'\int\sqrt{x^2-a^2}\,dx=\frac x2\sqrt{x^2-a^2}+\frac{a^2}2\ln\left|\frac{\sqrt{x^2-a^2}+x}{|a|}\right|+C'),note('The final source line changes the derived negative logarithm coefficient to plus. Keep the minus from the preceding derivation. For a ≠ 0, the corrected result is valid on each of x > |a| and x < −|a|; division by |a| only shifts the integration constant. The case a = 0 reduces to integrating |x| and should be handled separately.'),heading('6.4.3 Evaluation of integrals using integration by parts'),heading('Example 11'),paragraph(r'Evaluate the integral \(\int x\ln x\,dx\).'),heading('Solution'),paragraph('The integral rule ∫u dv = uv − ∫v du with substitution u = ln x and dv/dx = x is used to obtain:'),eq(r'\int x\ln x\,dx=\ln x\left(\frac{x^2}2\right)-\int\frac{x^2}2\left(\frac1x\right)\,dx,\quad\frac{du}{dx}=\frac1x,\quad dv=x\,dx,\quad v=\frac{x^2}2'),eq(r'=\frac{x^2}2\ln x-\frac12\int x\,dx+C=\frac{x^2}2\ln x-\frac12\left(\frac{x^2}2\right)+C=\frac{x^2}2\ln x-\frac{x^2}4+C'),heading('Example 12'),paragraph(r'Evaluate the integral \(\int e^x\sin x\,dx\).'),heading('Solution'),paragraph('The integral is'),eq(r'I=\int e^x\sin x\,dx','i'),paragraph('The integral rule ∫u dv = uv − ∫v du with substitution u = eˣ (let u be either eˣ or sin x) and dv/dx = sin x is used to obtain:'),eq(r'I=\int e^x\sin x\,dx=e^x(-\cos x)-\int(-\cos x)e^x\,dx,\quad\frac{du}{dx}=e^x,\quad dv=\sin x\,dx'),eq(r'=-e^x\cos x+\int e^x\cos x\,dx','ii'),paragraph('It appears that we have not made any progress since we cannot evaluate the new integral. However, the form of the new integrand prompts us to apply the technique a second time and see what happens.'),paragraph('Again, the integral of the integral part of equation (ii) with substitution u = eˣ and dv/dx = cos x is used in (ii) to obtain:'),eq(r'I=\int e^x\sin x\,dx=-e^x\cos x+\left[\int e^x\cos x\,dx\right]'),eq(r'=-e^x\cos x+\left[e^x\sin x-\int\sin x e^x\,dx\right]+C,\quad\frac{du}{dx}=e^x,\quad dv=\cos x\,dx'),eq(r'I=-e^x\cos x+e^x\sin x-\int e^x\sin x\,dx+C'),eq(r'I=-e^x\cos x+e^x\sin x-I+C'),eq(r'2I=e^x(\sin x-\cos x)+C'),eq(r'I=\frac{e^x(\sin x-\cos x)}2+\frac C2'),paragraph('Thus,'),eq(r'\int e^x\sin x\,dx=\frac{e^x(\sin x-\cos x)}2+C')])]
