EXAMPLES=[]
for n,q,steps,a in [
 (11,'Evaluate ∫x ln x dx.',['The real logarithm requires x > 0.','Choose u = ln x and dv = x dx.','Then du = dx/x and v = x²/2.','Integration by parts gives ∫x ln x dx = (x²/2)ln x − ∫(x²/2)(1/x) dx.','The remaining integrand is x/2, whose integral is x²/4.','Thus the antiderivative is (x²/2)ln x − x²/4 + C.','Check: differentiating the first term gives x ln x + x/2, and differentiating −x²/4 gives −x/2, leaving x ln x.'],'(x²/2)ln x − x²/4 + C, x > 0.'),
 (12,'Evaluate ∫eˣ sin x dx.',['Let I = ∫eˣ sin x dx. Choose u = eˣ and dv = sin x dx.','Then du = eˣdx and v = −cos x, so I = −eˣcos x + ∫eˣcos x dx.','For J = ∫eˣcos x dx, choose u = eˣ and dv = cos x dx.','This time v = sin x, giving J = eˣsin x − ∫eˣsin x dx = eˣsin x − I.','Substitute into the first relation: I = −eˣcos x + eˣsin x − I.','Collect like terms: 2I = eˣ(sin x−cos x); hence I = eˣ(sin x−cos x)/2 + C.','Check with the product rule: the derivative is eˣ(sin x−cos x)/2 + eˣ(cos x+sin x)/2 = eˣsin x.'],'eˣ(sin x−cos x)/2 + C.')]:
 EXAMPLES.append({'id':'we-6-source-'+str(n),'num':str(n),'title':'Example '+str(n),'problem':q,'given':'The source product integrand.','method':'Integration by parts; repeat once for the exponential–trigonometric product.','steps':steps,'answer':a,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':161,'verification':'complete source example and all working checked'}]})
